        private static HashSet<string> availableTypeNames;

        public static int TotalCount => Items.Length;

        public static int AvailableCount
        {
            get
            {
                int count = 0;
                for (int i = 0; i < Items.Length; i++)
                {
                    if (IsAvailable(Items[i]))
                    {
                        count++;
                    }
                }

                return count;
            }
        }

        public static void DrawSummary(string sceneId, int maxItems)
        {
            GUILayout.Space(6);
            GUILayout.Label("Integration and social MMO BEE-251..413 + BEE-421..600: " + AvailableCount + "/" + TotalCount + " frameworks detected");
            GUILayout.Label("Mode: read-only diagnostics. No manager replacement, no direct mutation, no parallel gameplay.");
            GUILayout.Label("Hive View product art pass: BEE-541..600 active in SandboxPlayground; BEE-601 remains blocked.");
            DrawSceneItems(sceneId, maxItems);
        }

        public static void DrawSceneItems(string sceneId, int maxItems)
        {
            int shown = 0;
            for (int i = Items.Length - 1; i >= 0; i--)
            {
                ColonyIntegrationDemoItem item = Items[i];
                if (!item.TargetsScene(sceneId))
                {
                    continue;
                }

                bool available = IsAvailable(item);
                GUILayout.Label(item.Bee + " " + item.Title + ": " + (available ? "framework present" : "blocked, framework missing"));
                GUILayout.Label("  " + item.Summary);
                if (!available)
                {
                    GUILayout.Label("  QA limit: display only; no runtime integration is claimed.");
                }

                shown++;
                if (shown >= maxItems)
                {
                    int remaining = CountSceneItems(sceneId) - shown;
                    if (remaining > 0)
                    {
                        GUILayout.Label("  +" + remaining + " linked BEE visible in the central sandbox panel.");
                    }

                    break;
                }
            }
        }

        private static int CountSceneItems(string sceneId)
        {
            int count = 0;
            for (int i = 0; i < Items.Length; i++)
            {
                if (Items[i].TargetsScene(sceneId))
                {
                    count++;
                }
            }

            return count;
        }

        private static bool IsAvailable(ColonyIntegrationDemoItem item)
        {
            EnsureTypeCache();
            for (int i = 0; i < item.RequiredTypeNames.Count; i++)
            {
                if (!availableTypeNames.Contains(item.RequiredTypeNames[i]))
                {
                    return false;
                }
            }

            return true;
        }

        private static void EnsureTypeCache()
        {
            if (availableTypeNames != null)
            {
                return;
            }

            availableTypeNames = new HashSet<string>(StringComparer.Ordinal);
            Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
            for (int i = 0; i < assemblies.Length; i++)
            {
                Type[] types = GetAssemblyTypes(assemblies[i]);
                for (int j = 0; j < types.Length; j++)
                {
                    Type type = types[j];
                    if (type != null)
                    {
                        availableTypeNames.Add(type.Name);
                    }
                }
            }
        }

        private static Type[] GetAssemblyTypes(Assembly assembly)
        {
            try
            {
                return assembly.GetTypes();
            }
            catch (ReflectionTypeLoadException exception)
            {
                return exception.Types;
            }
        }

        private readonly struct ColonyIntegrationDemoItem
        {
            public ColonyIntegrationDemoItem(string bee, string title, IReadOnlyList<string> sceneIds, string summary, IReadOnlyList<string> requiredTypeNames)
            {
                Bee = bee;
                Title = title;
                SceneIds = sceneIds;
                Summary = summary;
                RequiredTypeNames = requiredTypeNames;
            }

            public string Bee { get; }
            public string Title { get; }
            public IReadOnlyList<string> SceneIds { get; }
            public string Summary { get; }
            public IReadOnlyList<string> RequiredTypeNames { get; }

            public bool TargetsScene(string sceneId)
            {
                for (int i = 0; i < SceneIds.Count; i++)
                {
                    if (string.Equals(SceneIds[i], sceneId, StringComparison.Ordinal))
                    {
                        return true;
                    }
                }

                return false;
            }
        }
    }
